// Time:  O(nlogn)
// Space: O(n)

// sort, greedy
class Solution {
public:
    long long maxTotal(vector<int>& value, vector<int>& limit) {
        vector<int> idxs(size(value));
        iota(begin(idxs), end(idxs), 0);
        sort(begin(idxs), end(idxs), [&](const auto& a, const auto& b) {
            return limit[a] != limit[b] ? limit[a] < limit[b] : value[a] > value[b];
        });
        int64_t result = 0;
        for (int i = 0, cnt = 0, prev = 0; i < size(idxs); ++i) {
            const auto& l = limit[idxs[i]];
            const auto& v = value[idxs[i]];
            if (l != prev) {
                cnt = 0;
                prev = l;
            }
            if (cnt < l) {
                result += v;
                ++cnt;
            }
        }
        return result;
    }
};

kamyu-c-maximum-total-importance-of-road:
// Time:  O(n)
// Space: O(n)

// greedy, counting sort
class Solution {
public:
    long long maximumImportance(int n, vector<vector<int>>& roads) {
        vector<int> degree(n);
        for (const auto& r : roads) {
            ++degree[r[0]];
            ++degree[r[1]];
        }
        inplace_counting_sort(&degree, false);
        int64_t result = 0;
        for (int i = 0; i < n; ++i) {
            result += (i + 1ll) * degree[i];
        }
        return result;
    }

private:
    void inplace_counting_sort(vector<int> *nums, bool is_reverse) {
        const int max_num = *max_element(cbegin(*nums), cend(*nums));
        vector<int> count(max_num + 1);
        for (const auto& num : *nums) {
            ++count[num];
        }
        for (int i = 1; i < size(count); ++i) {
            count[i] += count[i - 1];
        }
        for (int i = size(*nums) - 1; i >= 0; --i) {  // inplace but unstable sort
            while ((*nums)[i] >= 0) {
                --count[(*nums)[i]];
                const int j = count[(*nums)[i]];
                tie((*nums)[i], (*nums)[j]) = pair((*nums)[j], ~(*nums)[i]);
            }
        }
        for (auto& num : *nums) {
            num = ~num;  // restore values
        }
        if (is_reverse) {  // unstable sort
            reverse(begin(*nums), end(*nums));
        }
    }
};

