                    bst2.emplace(grid[i + di][j + k]);
                }
            }
            if (i + 1 == size(grid) - (k-1)) {
                continue;
            }
            for (int dj = 0; dj < k; ++dj) {
                bst.erase(bst.find(grid[i][0 + dj]));
                bst.emplace(grid[i + k][0 + dj]);
            }
        }
        return result;
    }
};

