public:
    int garbageCollection(vector<string>& garbage, vector<int>& travel) {
        int result = 0;
        unordered_map<char, int> lookup;
        for (int i = 0; i < size(garbage); ++i) {
            for (const auto& c : garbage[i]) {
                lookup[c] = i;
            }
            if (i + 1 < size(travel)) {
                travel[i + 1] += travel[i];
            }
            result += size(garbage[i]);
