kamyu-c-minimum-cost-for-tickets-0ud3g0u:
// Time:  O(n)
// space: O(1)

class Solution {
public:
    int mincostTickets(vector<int>& days, vector<int>& costs) {
        static vector<int> durations{1, 7, 30};

        const int W = durations.back();
        vector<int> dp(W, numeric_limits<int>::max());
        dp[0] = 0;
        vector<int> last_buy_days{0, 0, 0};
        for (int i = 1; i < days.size() + 1; ++i) {
            dp[i % W] = numeric_limits<int>::max();
            for (int j = 0; j < durations.size(); ++j) {
                while (i - 1 < days.size() &&
                       days[i - 1] > days[last_buy_days[j]] + durations[j] - 1) {
                    ++last_buy_days[j];  // Time: O(n)
                }
                dp[i % W] = min(dp[i % W], dp[last_buy_days[j] % W] + costs[j]);
            }
        }
        return dp[days.size() % W];
    }
};

kamyu-c-minimum-cost-good-caption-12fype:
// Time:  O(26 * n)
// Space: O(26 * n)

// dp, backtracing
class Solution {
public:
    string minCostGoodCaption(string caption) {
        static const int L = 3;

        const int n = size(caption);
        if (n < L) {
            return "";
        }
        vector<vector<pair<int, int>>> dp(n - L + 1, vector<pair<int, int>>(26));
        vector<pair<int, int>> mn(n - L + 1);
        for (int i = n - L; i >= 0; --i) {
            for (int j = 0; j < 26; ++j) {
                if (i == n - L) {
                    for (int k = i; k < i + L; ++k) {
                        dp[i][j].first += abs((caption[k] - 'a') - j);
                    }
                    dp[i][j].second = L;
                    continue;
                }
                dp[i][j] = pair(dp[i + 1][j].first + abs((caption[i] - 'a') - j), 1);
                if (i + L < n - 2) {
                    auto [curr, c] = mn[i + L];
                    for (int k = i; k < i + L; ++k) {
                        curr += abs((caption[k] - 'a') - j);
                    }
                    if (curr < dp[i][j].first || (curr == dp[i][j].first && c < j)) {
                        dp[i][j] = pair(curr, L);
                    }
                }
            }
            mn[i] = pair(dp[i][0].first, 0);
            for (int j = 1; j < 26; ++j) {
                mn[i] = min(mn[i], pair(dp[i][j].first, j));
            }
        }
        string result;
        for (int i = 0, j = mn[0].second, l = 1; i != n; i += l) {
            if (l == L) {
                j = mn[i].second;
            }
            l = dp[i][j].second;
            result.append(l, 'a' + j);
        }
        return result;
    }
};

