        unordered_map<int64_t, int> dist = {{s, 0}};
        unordered_set<int64_t> lookup;
        while (size(lookup) != size(dist)) {
            pair<int, int64_t> mn = {INF, -1};
            for (const auto& [u, d] : dist) {
                if (!lookup.count(u)) {
                    mn = min(mn, pair(d, u));
