            const auto& [d, u] = mn;
            lookup.emplace(u);
            if (u == t) {
                return d;
            }
            for (const auto& [v, c] : adj[u]) {
                if (!dist.count(v) || dist[v] > d + c) {
                    dist[v] = d + c;
