            const auto& [x1, y1] = x_y(u);
            for (const auto& [v, _] : adj) {
                const auto& [x2, y2] = x_y(v);
                if (!dist.count(v) || dist[v] > d + abs(x2 - x1) + abs(y2 - y1)) {
                    dist[v] = d + abs(x2 - x1) + abs(y2 - y1);
                }
            }
        }
        return -1;
    }
};

