                        break;
                    }
                }
                if (ok) {
                    dp[(i + size(p)) % w] = min(dp[(i + size(p)) % w], dp[i % w] + c);
                }
            }
        }
        return dp[size(source) % w] != INF ? dp[size(source) % w] : -1;
