            adj[e[1]].emplace_back(e[0]);
        }
        int result = n - 1;
        const function<int64_t (int, int)> dfs = [&](int u, int p) {
            int64_t mx = 0;
            int cnt = 0;
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& c = dfs(v, u);
                if (c < mx) {
