// Time:  O(nlogn + klogk + klogn)
// space: O(n + k)

class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        sort(begin(intervals), end(intervals));
        vector<pair<int, int>> sorted_queries;
        for (int i = 0; i < size(queries); ++i) {
            sorted_queries.emplace_back(queries[i], i);
        }
        sort(begin(sorted_queries), end(sorted_queries));
        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> min_heap;
        int i = 0;
        vector<int> result(size(queries), -1);
        for (const auto& [q, idx] : sorted_queries) {
            for (; i != size(intervals) && intervals[i][0] <= q; ++i) {
                min_heap.emplace(intervals[i][1] - intervals[i][0] + 1, i);
            }
            while (!empty(min_heap) && intervals[min_heap.top().second][1] < q) {
                min_heap.pop();
            }
            result[idx] = (!empty(min_heap)) ? min_heap.top().first : -1;
        }
        return result;
    }
};

kamyu-c-minimum-inversion-count-in-subar:
// Time:  O(nlogn)
// Space: O(n)

// sort, coordinate compression, fenwick tree, sliding window
class BIT {
public:
    BIT(int n) : bit_(n + 1) {  // 0-indexed
    }

    void add(int i, int val) {
        ++i;
        for (; i < size(bit_); i += lower_bit(i)) {
            bit_[i] += val;
        }
    }

    int query(int i) const {
        ++i;
        int total = 0;
        for (; i > 0; i -= lower_bit(i)) {
            total += bit_[i];
        }
        return total;
    }

private:
    inline int lower_bit(int i) const {
        return i & -i;
    }

    vector<int> bit_;
};

class Solution {
public:
    long long minInversionCount(vector<int>& nums, int k) {
        vector<int> vals(nums);
        ranges::sort(vals);
        vals.erase(unique(begin(vals), end(vals)), end(vals));
        unordered_map<int, int> val_to_idx;
        for (int i = 0; i < size(vals); ++i) {
            val_to_idx[vals[i]] = i;
        }
        int64_t result = numeric_limits<int64_t>::max(), cnt = 0;
        BIT bit(size(val_to_idx));
        for (int i = 0; i < size(nums); ++i) {
            bit.add(val_to_idx[nums[i]], +1);
            cnt += bit.query(size(val_to_idx) - 1) - bit.query(val_to_idx[nums[i]]);
            if (i < k - 1) {
                continue;
            }
            result = min(result, cnt);
            cnt -= bit.query(val_to_idx[nums[i - (k - 1)]] - 1);
            bit.add(val_to_idx[nums[i - (k - 1)]], -1);
        }
        return result;
    }
};

kamyu-c-minimum-jumps-to-reach-end-via-p:
// Time:  precompute: O(r)
//        runtime:    O(nlogr)
// Space: O(r + nlogr)

// number theory, bfs
vector<int> linear_sieve_of_eratosthenes(int n) {  // Time: O(n), Space: O(n)
    vector<int> spf(n + 1, -1);
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return spf;
};

const int MAX_NUM = 1e6;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_NUM);
class Solution {
public:
    int minJumps(vector<int>& nums) {
        unordered_map<int, vector<int>> adj;
        for (int i = 0; i < size(nums); ++i) {
            int x = nums[i];
            while (x != 1) {
                const auto& p = SPF[x];
                while (x % p == 0) {
                    x /= p;
                }
                adj[p].emplace_back(i);
            }
        }
        vector<int> dist(size(nums), -1);
        dist[0] = 0;
        vector<int> q = {0};
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& i : q) {
                if (i == size(nums) - 1) {
                    return dist.back();
                }
                for (const auto& di : {-1, +1}) {
                    const int ni = i + di;
                    if (0 <= ni && ni < size(nums) && dist[ni] == -1) {
                        dist[ni] = dist[i] + 1;
                        new_q.emplace_back(ni);
                    }
                }
                const int p = nums[i];
                if (SPF[p] != p || !adj.count(p)) {
                    continue;
                }
                for (const auto& ni : adj[p]) {
                    if (dist[ni] != -1) {
                        continue;
                    }
                    dist[ni] = dist[i] + 1;
                    new_q.emplace_back(ni);
                }
                adj.erase(p);
            }
            q = move(new_q);
        }
        return -1;
    }
};

kamyu-c-minimum-jumps-to-reach-home-0mkx:
// Time:  O(max(x, max(forbidden)) + a + (b+a))
// Space: O(max(x, max(forbidden)) + a + (b+a))

class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        int max_f = *max_element(cbegin(forbidden), cend(forbidden));
        int max_val = (a >= b) ? x + b : max(x, max_f) + a + b;  // a may be a non-periodic area, (a+b) is a periodic area which is divided by gcd(a, b) and all points are reachable
        vector<unordered_set<int>> lookup(2); 
        for (const auto& pos : forbidden) {
            lookup[0].emplace(pos);
            lookup[1].emplace(pos);
        }
        int result = 0;
        vector<pair<int, int>> q = {{0, true}};
        lookup[0].emplace(0);
        while (!empty(q)) {
            vector<pair<int, int>> new_q;
            for (const auto& [pos, can_back] : q) {
                if (pos == x) {
                    return result;
                }
                if (pos + a <= max_val && !lookup[0].count(pos + a)) {
                    lookup[0].emplace(pos + a);
                    new_q.emplace_back(pos + a, true);
                }
                if (!can_back) {
                    continue;
                }
                if (pos - b >= 0 && !lookup[1].count(pos - b)) {
                    lookup[1].emplace(pos - b);
                    new_q.emplace_back(pos - b, false);
                }
            }
            q = move(new_q);
            ++result;
        }
        return -1;
    }
};

kamyu-c-minimum-k-to-reduce-array-within:
// Time:  O(nlogr + nlogn)
// Space: O(1)

// binary search
class Solution {
public:
    int minimumK(vector<int>& nums) {
        const auto& binary_search = [](auto left, auto right, const auto& check) {
            while (left <= right) {
                const auto& mid = left + (right - left) / 2;
                if (check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return left;
        };

        const auto& ceil_divide = [](int a, int b) {
            return (a + b - 1) / b;
        };

        const auto& check = [&](int k) {
            int64_t result = 0;
            for (const auto& x : nums) {
                result += ceil_divide(x, k);
                if (result > static_cast<int64_t>(k) * k) {
                    return false;
                }
            }
            return true;
        };

        const auto& right = max(ranges::max(nums), static_cast<int>(ceil(sqrt(size(nums)))));
        return binary_search(1, right, check);
    }
};

kamyu-c-minimum-knight-moves-0gatfg3:
// Time:  O(1)
// Space: O(1)

class Solution {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    int minKnightMoves(int x, int y) {
        // we can observe from:
        // [0]
        // [3, 2]
        // [2,(1),4]
        // [3, 2, 3, 2]
        // [2, 3,(2) 3, 4]
        // [3, 4, 3, 4, 3, 4]
        // [4, 3, 4,(3),4, 5, 4]
        // [5, 4, 5, 4, 5, 4, 5, 6]
        // [4, 5, 4, 5,(4),5, 6, 5, 6]
        // [5, 6, 5, 6, 5, 6, 5, 6, 7, 6]
        // [6, 5, 6, 5, 6,(5),6, 7, 6, 7, 8]
        // [7, 6, 7, 6, 7, 6, 7, 6, 7, 8, 7, 8]
        // [6, 7, 6, 7, 6, 7,(6),7, 8, 7, 8, 9, 8]
        // [7, 8, 7, 8, 7, 8, 7, 8, 7, 8, 9, 8, 9, 10]
        // [8, 7, 8, 7, 8, 7, 8,(7),8, 9, 8, 9, 10, 9, 10]
        // [9, 8, 9, 8, 9, 8, 9, 8, 9, 8, 9, 10, 9, 10, 11, 10]

        x = abs(x), y = abs(y);
        if (x < y) {
            swap(x, y);
        }
        static const unordered_map<pair<int, int>, int, PairHash<int>> lookup =
            {{{1, 0}, 3}, {{2, 2}, 4}};  // special cases
        if (lookup.count({x, y})) {
            return lookup.at({x, y});
        }
        const auto& k = x - y;
        if (y > k) {
            // if 2y > x, every period 3 of y (or k) with fixed another is increased by 2 (or 1)
            // and start from (2k, k) with (k) when y = k (diagonal line)
            // ex. (0, 0) ~ (12, 12) ~ ... : 0 => 2,4(special case),2 => 4,4,4 => 6,6,6 => 8,8,8 => ...
            // ex. (2, 1) ~ (14, 13) ~ ... : 1 => 3,3,3 => 5,5,5 => 7,7,7 => 9,9,9 => ...
            return k + 2 * ((y - k - 1) / 3 + 1);
        }
        // if 2y <= x, every period 4 of k (or y) with fixed another is increased by 2
        // and start from (2k, k) with (k) when y = k (vertical line)
        // ex. (0, 0) ~ (11, 0) ~ ... : 0,3(special case),2,3 => 2,3,4,5 => 4,5,6,7 => ...
        // ex. (2, 1) ~ (13, 1) ~ ... : 1,2,3,4 => 3,4,5,6 => 5,6,7,8 => ...
        return k - 2 * ((k - y) / 4);
    }
};

// Time:  O(n^2)
// Space: O(n^2)
class Solution2 {
public:
    int minKnightMoves(int x, int y) {
        return dp(x, y);
    }

private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

    int dp(int x, int y) {
        static unordered_map<pair<int, int>, int, PairHash<int>> lookup =
            {{{0, 0}, 0}, {{1, 1}, 2}, {{1, 0}, 3}};  // special cases
        x = abs(x), y = abs(y);
        if (x < y) {
            swap(x, y);
        }
        if (!lookup.count({x, y})) {  // greedy, smaller x, y is always better if not special cases
            lookup[{x, y}] = min(dp(x - 1, y - 2), dp(x - 2, y - 1)) + 1;
        }
        return lookup[{x, y}];
    }
};

