            }
            if (!lookup.count(x)) {
                lookup[x] = x - y;
                for (const auto& d : {5, 11}) {
                    lookup[x] = min(lookup[x], min(x % d, d - x % d) + memoization(x / d + (d - x % d < x % d ? 1 : 0)) + 1);
