        if (y >= x) {
            return y - x;
        }
        const int upper_bound = x + (x - y);
        unordered_set<int> lookup = {x};
        vector<int> q = {x};
        for (int d = 0; !empty(q); ++d) {
            vector<int> new_q;
            for (const auto& x: q) {
                if (x == y) {
                    return d;
                }
                vector<int> candidates = {x + 1, x - 1};
                for (const auto& d : {5, 11}) {
                    if (x % d == 0) {
                        candidates.emplace_back(x / d);
                    }
                }
                for (const auto& new_x : candidates) {
                    if (!(0 <= new_x && new_x <= upper_bound && !lookup.count(new_x))) {
                        continue;
                    }
                    lookup.emplace(new_x);
                    new_q.emplace_back(new_x);
                }
            }
            q = move(new_q);
        }
        return -1;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> minOperations(string boxes) {
        vector<int> result(size(boxes)); 
        for (int i = 0, accu = 0, cnt = 0; i < size(boxes); ++i) {
           result[i] += accu;
           cnt += (boxes[i] == '1') ? 1 : 0;
           accu += cnt;
        }
        for (int i = size(boxes) - 1, accu = 0, cnt = 0; i >= 0; --i) {
            result[i] += accu;
            cnt += (boxes[i] == '1') ? 1 : 0;
            accu += cnt;
        }
        return result;
    }
};
